describe('File Upload Size Validation', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('input[type="file"]').as('fileInput');
  });

  it('should reject files larger than 5MB with error message', () => {
    const largeFileName = 'large-file.pdf';
    const fileSizeInBytes = 6 * 1024 * 1024; // 6MB

    cy.fixture('large-file.pdf', 'binary')
      .then(fileContent => {
        const blob = Cypress.Blob.binaryStringToBlob(fileContent, 'application/pdf');
        const file = new File([blob], largeFileName, { type: 'application/pdf' });

        cy.get('@fileInput').selectFile({
          contents: Cypress.Buffer.from(new Array(fileSizeInBytes).fill(0)),
          fileName: largeFileName,
          mimeType: 'application/pdf'
        }, { force: true });
      });

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'File size must not exceed 5MB');

    cy.get('[data-testid="upload-button"]')
      .should('be.disabled');

    cy.get('[data-testid="file-preview"]')
      .should('not.exist');
  });

  it('should accept files exactly at 5MB limit', () => {
    const validFileName = 'valid-file.pdf';
    const fileSizeInBytes = 5 * 1024 * 1024; // 5MB

    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from(new Array(fileSizeInBytes).fill(0)),
      fileName: validFileName,
      mimeType: 'application/pdf'
    }, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    cy.get('[data-testid="upload-button"]')
      .should('not.be.disabled');

    cy.get('[data-testid="file-preview"]')
      .should('be.visible')
      .and('contain', validFileName);
  });

  it('should accept files smaller than 5MB', () => {
    const smallFileName = 'small-file.txt';
    const fileSizeInBytes = 2 * 1024 * 1024; // 2MB

    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from(new Array(fileSizeInBytes).fill(0)),
      fileName: smallFileName,
      mimeType: 'text/plain'
    }, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    cy.get('[data-testid="upload-button"]')
      .should('not.be.disabled');

    cy.get('[data-testid="file-size-display"]')
      .should('contain', '2 MB');
  });

  it('should clear error message when replacing oversized file with valid file', () => {
    const largeFileName = 'large-file.pdf';
    const validFileName = 'valid-file.pdf';
    const largeFileSizeInBytes = 6 * 1024 * 1024; // 6MB
    const validFileSizeInBytes = 3 * 1024 * 1024; // 3MB

    // Upload large file
    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from(new Array(largeFileSizeInBytes).fill(0)),
      fileName: largeFileName,
      mimeType: 'application/pdf'
    }, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'File size must not exceed 5MB');

    // Replace with valid file
    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from(new Array(validFileSizeInBytes).fill(0)),
      fileName: validFileName,
      mimeType: 'application/pdf'
    }, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    cy.get('[data-testid="file-preview"]')
      .should('be.visible')
      .and('contain', validFileName);
  });

  it('should validate file size on form submission attempt', () => {
    const largeFileName = 'large-file.pdf';
    const fileSizeInBytes = 7 * 1024 * 1024; // 7MB

    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from(new Array(fileSizeInBytes).fill(0)),
      fileName: largeFileName,
      mimeType: 'application/pdf'
    }, { force: true });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'File size must not exceed 5MB');

    cy.get('[data-testid="success-message"]')
      .should('not.exist');
  });
});
